import {
  TEXT_ALIGN,
  TEXT_LINES,
  TEXT_ROLES,
  TEXT_TONES,
  TEXT_WEIGHTS,
  toneToken,
  type TextRole
} from '../components/text-props'

const HEADER = `/*
 * Stencil text CSS for StText: one rule per allowed prop value, each reading a token.
 * GENERATED by \`pnpm stencil:tokens\` from stencil/components/text-props.ts. Do not edit by hand.
 * The type, tone, and weight rules share one specificity, so a later rule overrides an earlier one.
 */
`

const ALIGN = { start: 'start', center: 'center', end: 'end' }

/** Renders the StText rules as one stylesheet. */
export function renderTextCss(): string {
  const rules: string[] = []
  for (const role of Object.keys(TEXT_ROLES) as TextRole[]) {
    for (const size of TEXT_ROLES[role]) {
      rules.push(
        `.st-text[data-st-type='${role}-${size}'] { font: var(--st-type-${role}-${size}); }`
      )
    }
  }
  for (const tone of TEXT_TONES) {
    rules.push(`.st-text[data-st-tone='${tone}'] { color: var(${toneToken(tone)}); }`)
  }
  for (const weight of TEXT_WEIGHTS) {
    rules.push(
      `.st-text[data-st-weight='${weight}'] { font-weight: var(--st-font-weight-${weight}); }`
    )
  }
  for (const align of TEXT_ALIGN) {
    rules.push(`.st-text[data-st-align='${align}'] { text-align: ${ALIGN[align]}; }`)
  }
  rules.push(
    '.st-text[data-st-truncate] { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }'
  )
  for (const lines of TEXT_LINES) {
    rules.push(
      `.st-text[data-st-lines='${lines}'] { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: ${lines}; }`
    )
  }
  return `${HEADER}\n${rules.join('\n')}\n`
}
